let latestMessageScrollKey=null,latestMessageScrollFrame=null,latestMessageScrollTimer=null;
function messageScrollKey(data){let last=data?.messages?.[data.messages.length-1];return JSON.stringify([data?.active_character_id,last?.id,last?.role,last?.content,(last?.artifacts||[]).map(item=>item.id)])}
function scrollMessagesToLatest(messages){
  cancelAnimationFrame(latestMessageScrollFrame);clearTimeout(latestMessageScrollTimer);messages.scrollTop=messages.scrollHeight;
  latestMessageScrollFrame=requestAnimationFrame(()=>{messages.scrollTop=messages.scrollHeight});
  latestMessageScrollTimer=setTimeout(()=>{messages.scrollTop=messages.scrollHeight},100);
}
function syncLatestMessageScroll(data,messages){
  let key=messageScrollKey(data);
  if(key===latestMessageScrollKey)return;
  latestMessageScrollKey=key;scrollMessagesToLatest(messages);
  let latest=messages.lastElementChild;
  latest?.querySelectorAll("img,video,audio").forEach(media=>{
    media.addEventListener(media.tagName==="IMG"?"load":"loadedmetadata",()=>scrollMessagesToLatest(messages),{once:true});
    if(media.tagName==="IMG"?media.complete:media.readyState>=1)scrollMessagesToLatest(messages);
  });
}

