const continueVideoDialog=$("continue-video-dialog"),continueVideoForm=$("continue-video-form");let continueArtifactId=null,continueVideoDraft=null;
continueVideoForm.innerHTML='<div class="dialog-head"><h2>Continue video</h2><button type="button">Close</button></div><div id="continue-video-compose"><p class="note">The next clip starts from a frame near the end of this video. Describe only what happens next. Use actual character names for actions and dialogue, for example: Avery turns and says &quot;Ready.&quot;</p><label>Next action<textarea name="content" rows="6" maxlength="4000" required placeholder="Avery turns toward the window and says &quot;Look at that.&quot;"></textarea></label><button class="primary">Review continuation</button></div><div id="continue-video-review" hidden><p class="review-note">Confirm who says each exact line before generation begins.</p><div id="continue-speaker-turns"></div><p id="continue-silent-note" class="note" hidden>No quoted dialogue was found. This continuation will be silent.</p><div class="dialog-actions"><button type="button" id="continue-video-back">Back</button><button class="primary" type="button" id="continue-video-confirm">Confirm and generate</button></div></div><p class="note" id="continue-video-message"></p>';
function imageStageSize(){let style=getComputedStyle(imageViewStage);return{width:Math.max(1,imageViewStage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)),height:Math.max(1,imageViewStage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom))}}
function updateImageViewScale(){if(!imageViewImage.naturalWidth||!imageViewer.open)return;if(imageViewMode.value==="full"){imageViewImage.style.width=imageViewImage.naturalWidth+"px";imageViewImage.style.height=imageViewImage.naturalHeight+"px";imageViewMode.options[0].textContent="Fit to screen";imageViewMode.options[1].textContent="Full size (100%)";return}let available=imageStageSize(),scale=Math.min(1,available.width/imageViewImage.naturalWidth,available.height/imageViewImage.naturalHeight);imageViewImage.style.width=Math.max(1,Math.floor(imageViewImage.naturalWidth*scale))+"px";imageViewImage.style.height=Math.max(1,Math.floor(imageViewImage.naturalHeight*scale))+"px";imageViewMode.options[0].textContent="Fit to screen ("+Math.round(scale*100)+"%)";imageViewMode.options[1].textContent="Full size (100%)"}
function setImageViewMode(mode){imageViewStage.classList.toggle("full-size",mode==="full");requestAnimationFrame(updateImageViewScale)}
function openImageViewer(source){let src=source.currentSrc||source.src;if(!src)return;imageViewImage.alt=source.alt||"Expanded image";imageViewMode.value="fit";imageViewer.showModal();imageViewImage.src=src;requestAnimationFrame(()=>setImageViewMode("fit"))}
document.addEventListener("click",event=>{let source=event.target.closest(".media img, #character-preview");if(source)openImageViewer(source)});
document.addEventListener("keydown",event=>{if((event.key==="Enter"||event.key===" ")&&event.target.matches(".media img, #character-preview")){event.preventDefault();openImageViewer(event.target)}});
$("character-preview").tabIndex=0;$("character-preview").setAttribute("role","button");$("character-preview").setAttribute("aria-label","Open character reference image");
imageViewImage.addEventListener("load",updateImageViewScale);
imageViewMode.addEventListener("change",()=>setImageViewMode(imageViewMode.value));
$("image-view-close").addEventListener("click",()=>imageViewer.close());
imageViewer.addEventListener("click",event=>{if(event.target===imageViewer)imageViewer.close()});
window.addEventListener("resize",()=>{if(imageViewer.open)requestAnimationFrame(updateImageViewScale)});
const anchorApprove=document.createElement('button');anchorApprove.id='image-anchor-approve';anchorApprove.type='button';anchorApprove.textContent='Use as scene anchor';imageViewer.querySelector('.image-view-toolbar').prepend(anchorApprove);
function viewedArtifactId(){let match=imageViewImage.src.match(/\/api\/v1\/artifacts\/(\d+)/);return match?Number(match[1]):null}
imageViewer.addEventListener('toggle',()=>{if(imageViewer.open)anchorApprove.hidden=!viewedArtifactId()});imageViewImage.addEventListener('load',()=>anchorApprove.hidden=!viewedArtifactId());
anchorApprove.onclick=async()=>{let artifact_id=viewedArtifactId(),scene=state.active_scene,aspect=state.settings.aspect_mode;if(!artifact_id||!scene||!confirm('Use this image as the '+aspect+' anchor for '+scene.name+'?'))return;anchorApprove.disabled=true;try{let job=await api('/api/v1/scenes/'+scene.id+'/anchor',{method:'POST',body:JSON.stringify({artifact_id,aspect_mode:aspect})});imageViewer.close();setBusy(true);$('hint').textContent='Preparing the scene anchor…';await load();watch(job.job_id)}catch(err){$('hint').textContent=err.message}finally{anchorApprove.disabled=false}};
const sceneButton=document.createElement("button");sceneButton.id="scene-open";sceneButton.type="button";sceneButton.textContent="Scene";$('character-open').before(sceneButton);
const sceneDialog=document.createElement("dialog");sceneDialog.id="scene-dialog";sceneDialog.innerHTML='<form id="scene-form"><div class="dialog-head"><h2>Scene library</h2><button type="button" id="scene-close">Close</button></div><label>Active scene<select id="scene-select"><option value="">No scene</option></select></label><label>Scene name<input name="name" maxlength="120" placeholder="Malibu beach house"></label><label>Environment description<textarea name="description" rows="6" maxlength="2000" placeholder="Describe the empty location, lighting, furnishings, props, and camera layout."></textarea></label><p class="note">Scenes are reusable environments. Characters are added only when media is generated.</p><section id="scene-anchor"><strong id="scene-anchor-title">Visual anchor</strong><img id="scene-anchor-preview" alt="Current scene anchor" hidden><p class="note" id="scene-anchor-status">No anchor for this aspect.</p><div class="dialog-actions"><button type="button" id="scene-new">New scene</button><button type="button" id="scene-anchor-generate">Generate anchor</button><button type="button" id="scene-anchor-clear" hidden>Remove anchor</button></div></section><p class="note" id="scene-message"></p><div class="dialog-actions"><button type="button" id="scene-clear">Delete scene</button><button class="primary" type="submit">Save scene</button></div></form>';document.body.append(sceneDialog);
const sceneForm=$('scene-form');function renderScene(d){let locked=!!(d.active_job||d.active_creation),scene=d.active_scene,ready=scene?.active_asset?.ready;sceneButton.disabled=locked;sceneButton.textContent=scene?(ready?'Scene: '+scene.name+' ✓':'Scene: '+scene.name):'Scene: off'}
let autoResumeCreation=true;const originalRender=render;render=function(d){let messages=$("messages"),previousKey=messageScrollKey(state),previousScroll=messages.scrollTop;originalRender(d);renderScene(d);if(messageScrollKey(d)===previousKey)messages.scrollTop=previousScroll;else syncLatestMessageScroll(d,messages);if(autoResumeCreation&&d.active_creation&&!document.getElementById('creation-dialog').open){autoResumeCreation=false;queueMicrotask(()=>resumeCreation(d.active_creation.character_id))}};
function fillSceneDialog(scene=state.active_scene){let select=$('scene-select');select.replaceChildren(new Option('No scene',''));state.scenes.forEach(item=>select.add(new Option(item.name,item.id,item.id===scene?.id,item.id===scene?.id)));sceneForm.dataset.id=scene?.id||'';sceneForm.name.value=scene?.name||'';sceneForm.description.value=scene?.description||'';let aspect=state.settings.aspect_mode,asset=scene?.assets?.[aspect],preview=$('scene-anchor-preview');$('scene-anchor-title').textContent=aspect[0].toUpperCase()+aspect.slice(1)+' visual anchor';preview.hidden=!asset?.artifact_id;preview.src=asset?.artifact_id?'/api/v1/artifacts/'+asset.artifact_id:'';$('scene-anchor-status').textContent=asset?.ready?'Approved character-free anchor is active.':'No approved anchor for this aspect; text continuity will be used.';$('scene-anchor-clear').hidden=!asset?.ready;$('scene-anchor-generate').disabled=!scene;$('scene-clear').disabled=!scene}
sceneButton.onclick=()=>{$('scene-message').textContent='';fillSceneDialog();sceneDialog.showModal()};
$('scene-close').onclick=()=>sceneDialog.close();$('scene-new').onclick=()=>{sceneForm.dataset.id='';sceneForm.name.value='';sceneForm.description.value='';$('scene-select').value='';fillSceneDialog(null);sceneForm.name.focus()};
$('scene-select').onchange=async e=>{let id=e.target.value?Number(e.target.value):null;try{await api('/api/v1/active-scene',{method:'PUT',body:JSON.stringify({scene_id:id})});await load();fillSceneDialog(state.active_scene);renderScene(state)}catch(err){$('scene-message').textContent=err.message}};
sceneForm.onsubmit=async e=>{e.preventDefault();try{let id=Number(sceneForm.dataset.id),url=id?'/api/v1/scenes/'+id:'/api/v1/scenes',method=id?'PUT':'POST';await api(url,{method,body:JSON.stringify({name:sceneForm.name.value,description:sceneForm.description.value})});await load();fillSceneDialog(state.active_scene);renderScene(state);$('scene-message').textContent='Scene saved.'}catch(err){$('scene-message').textContent=err.message}};
$('scene-clear').onclick=async()=>{let scene=state.active_scene;if(!scene||!confirm('Delete scene '+scene.name+'?'))return;try{await api('/api/v1/scenes/'+scene.id,{method:'DELETE'});await load();fillSceneDialog(null);renderScene(state)}catch(err){$('scene-message').textContent=err.message}};
$('scene-anchor-generate').onclick=async()=>{let scene=state.active_scene,aspect=state.settings.aspect_mode;if(!scene)return;try{let job=await api('/api/v1/scenes/'+scene.id+'/anchor-candidate',{method:'POST',body:JSON.stringify({aspect_mode:aspect})});sceneDialog.close();setBusy(true);$('hint').textContent='Generating a character-free '+aspect+' scene anchor…';await load();watch(job.job_id)}catch(err){$('scene-message').textContent=err.message}};
$('scene-anchor-clear').onclick=async()=>{let scene=state.active_scene,aspect=state.settings.aspect_mode;if(!scene||!confirm('Remove the '+aspect+' anchor?'))return;try{await api('/api/v1/scenes/'+scene.id+'/anchor/'+aspect,{method:'DELETE'});await load();fillSceneDialog(state.active_scene);renderScene(state)}catch(err){$('scene-message').textContent=err.message}};
const modelBox=document.createElement('fieldset');modelBox.id='model-readiness';modelBox.innerHTML='<legend>Model readiness</legend><p class="note">Checks the selected Ollama model and models visible to the running ComfyUI server.</p><button type="button" id="models-check">Check models</button><div id="models-result" aria-live="polite"></div>';$('advanced-settings').before(modelBox);
const endpointBox=document.createElement('fieldset');endpointBox.id='endpoint-settings';endpointBox.innerHTML='<legend>Service endpoints</legend><label>Ollama endpoint<input name="endpoint_ollama" maxlength="500" placeholder="http://127.0.0.1:11434"></label><label>ComfyUI endpoint<input name="endpoint_comfyui" maxlength="500" placeholder="http://127.0.0.1:8188"></label><p class="note">Changes apply to newly queued work.</p>';$('advanced-settings').prepend(endpointBox);
async function checkModels(){let out=$('models-result'),button=$('models-check');button.disabled=true;out.textContent='Checking models…';try{let report=await api('/api/v1/models/readiness'),groups={missing:[],unverified:[],present:[]};report.models.forEach(item=>groups[item.status].push(item.name));out.replaceChildren();for(const [status,items] of Object.entries(groups)){if(!items.length)continue;let p=document.createElement('p');p.className='model-'+status;p.textContent=status[0].toUpperCase()+status.slice(1)+': '+items.join(', ');out.append(p)}if(Object.keys(report.errors).length){let p=document.createElement('p');p.textContent='Unavailable services: '+Object.keys(report.errors).join(', ');out.append(p)}}catch(err){out.textContent=err.message}finally{button.disabled=false}}
$('models-check').onclick=checkModels;$('settings-open').addEventListener('click',checkModels);
const diagnosticsDialog=$("diagnostics-dialog");let diagnosticsReport=null;
function diagnosticStatus(name,item){let row=document.createElement("div");row.className="diagnostic-row";let label=document.createElement("strong"),value=document.createElement("span");label.textContent=name;value.textContent=item.status+(item.latency_ms!=null?" · "+item.latency_ms+" ms":item.age_seconds!=null?" · heartbeat "+item.age_seconds+"s ago":"");row.append(label,value);return row}
async function loadDiagnostics(){let summary=$("diagnostics-summary"),jobs=$("diagnostics-jobs");summary.textContent="Checking services...";jobs.replaceChildren();$("diagnostics-message").textContent="";try{diagnosticsReport=await api("/api/v1/diagnostics");summary.replaceChildren();for(const [name,item] of Object.entries(diagnosticsReport.services))summary.append(diagnosticStatus(name[0].toUpperCase()+name.slice(1),item));let queue=document.createElement("p");queue.className="diagnostic-queue";queue.textContent="Queue: "+diagnosticsReport.queue.queued+" waiting, "+diagnosticsReport.queue.running+" running, "+diagnosticsReport.queue.failed+" failed, "+diagnosticsReport.queue.completed+" completed.";summary.append(queue);diagnosticsReport.jobs.forEach(job=>{let row=document.createElement("div"),title=document.createElement("strong"),detail=document.createElement("small");row.className="diagnostic-job";title.textContent="#"+job.id+" · "+(JOB_NAMES[job.type]||job.type)+" · "+job.status;detail.textContent=job.failure||job.phase||job.completed_at||job.created_at||"";row.append(title,detail);jobs.append(row)});if(!diagnosticsReport.jobs.length)jobs.textContent="No jobs recorded."}catch(err){summary.textContent=err.message}}
$("debug-open").onclick=()=>{diagnosticsDialog.showModal();loadDiagnostics()};
$("diagnostics-close").onclick=()=>diagnosticsDialog.close();
$("diagnostics-refresh").onclick=loadDiagnostics;
$("diagnostics-copy").onclick=async()=>{if(!diagnosticsReport)return;try{await navigator.clipboard.writeText(JSON.stringify(diagnosticsReport,null,2));$("diagnostics-message").textContent="Safe report copied."}catch(err){$("diagnostics-message").textContent="Copy failed. Select the report from browser developer tools."}};


/* Settings autosave */
let settingsSaveTimer=null,settingsSaveActive=false,settingsSaveDirty=false;
function settingsPayload(){let workflows={};state.settings.workflows.forEach(step=>workflows[step.key]=settingsForm["workflow_"+step.key].value);return{content_mode:settingsForm.content_mode.value,aspect_mode:settingsForm.aspect_mode.value,character_videos:settingsForm.character_videos.checked,model:settingsForm.model.value,endpoint_ollama:settingsForm.endpoint_ollama.value,endpoint_comfyui:settingsForm.endpoint_comfyui.value,debug_mode:settingsForm.debug_mode.checked,workflows,telegram:{enabled:settingsForm.telegram_enabled.checked,token:settingsForm.telegram_token.value}}}
function scheduleSettingsSave(delay=0){settingsSaveDirty=true;clearTimeout(settingsSaveTimer);let status=$("settings-save-status");if(status){status.textContent=delay?"Waiting to save…":"Saving…";status.className="note settings-save-status saving"}settingsSaveTimer=setTimeout(flushSettingsSave,delay)}
async function flushSettingsSave(){clearTimeout(settingsSaveTimer);settingsSaveTimer=null;if(settingsSaveActive||!settingsSaveDirty)return;settingsSaveDirty=false;settingsSaveActive=true;let status=$("settings-save-status"),payload=settingsPayload();if(status){status.textContent="Saving…";status.className="note settings-save-status saving"}try{let d=await api("/api/v1/settings",{method:"PATCH",body:JSON.stringify(payload)});state=d;snapshotKey=syncKey(d);$("mode").textContent=d.settings.content_mode+" / "+d.settings.aspect_mode;$("debug-open").hidden=!d.settings.debug_mode;if(payload.telegram.token)settingsForm.telegram_token.value="";$("telegram-status").textContent=d.settings.telegram.active?"Telegram is active.":d.settings.telegram.configured?"Token saved; restart required to activate Telegram.":"No Telegram bot is configured.";if(d.settings.telegram.restart_required)$("telegram-message").textContent="Restart CastWorkshop to apply Telegram changes.";if(status){status.textContent="Saved";status.className="note settings-save-status saved"}}catch(err){if(status){status.textContent="Could not save: "+err.message;status.className="note settings-save-status error"}}finally{settingsSaveActive=false;if(settingsSaveDirty)flushSettingsSave()}}
settingsForm.addEventListener("change",()=>scheduleSettingsSave());
settingsForm.model.addEventListener("input",()=>scheduleSettingsSave(700));
settingsForm.endpoint_ollama.addEventListener("input",()=>scheduleSettingsSave(700));
settingsForm.endpoint_comfyui.addEventListener("input",()=>scheduleSettingsSave(700));
settingsForm.onsubmit=e=>{e.preventDefault();scheduleSettingsSave()};
$("settings-open").addEventListener("click",()=>{let status=$("settings-save-status");if(status&&!settingsSaveActive&&!settingsSaveDirty){status.textContent="Changes save automatically.";status.className="note settings-save-status"}});

/* Continue a completed video from its final frame. */
PHASES.extracting_frame=["Preparing continuation frame",30];
function decorateContinuationButtons(){
  $("messages").querySelectorAll("video").forEach(video=>{
    let match=video.getAttribute("src")?.match(/\/api\/v1\/artifacts\/(\d+)/);if(!match)return;
    let artifactId=Number(match[1]);
    if(!video.parentElement.querySelector(".continue-video")){
      let button=document.createElement("button");button.type="button";button.className="continue-video";
      button.textContent="Continue video";button.disabled=!!state?.active_job;
      button.onclick=()=>{continueArtifactId=artifactId;continueVideoDraft=null;continueVideoForm.reset();$("continue-video-compose").hidden=false;$("continue-video-review").hidden=true;$("continue-video-message").textContent="";continueVideoDialog.showModal()};
      video.parentElement.append(button);
    }
    if(!video.parentElement.querySelector(".play-video-chain")){
      let sequence=document.createElement("button");sequence.type="button";sequence.className="play-video-chain";
      sequence.textContent="Play sequence";sequence.onclick=()=>openVideoChain(artifactId);
      video.parentElement.append(sequence);
    }
  })
}
new MutationObserver(decorateContinuationButtons).observe($("messages"),{childList:true,subtree:true});
continueVideoForm.querySelector(".dialog-head button").onclick=()=>continueVideoDialog.close();
continueVideoForm.onsubmit=async e=>{e.preventDefault();let content=continueVideoForm.content.value.trim();if(!content)return;
  let submit=continueVideoForm.querySelector("#continue-video-compose button.primary");submit.disabled=true;$("continue-video-message").textContent="Reviewing continuation…";
  try{let d=await api("/api/v1/artifacts/"+continueArtifactId+"/continue",{method:"POST",body:JSON.stringify({content})});if(!d.requires_speaker_confirmation){continueVideoDialog.close();setBusy(true);await watch(d.job_id);return}continueVideoDraft=d;let box=$("continue-speaker-turns");box.replaceChildren();d.dialogue_turns.forEach((turn,index)=>{let row=document.createElement("label"),select=document.createElement("select"),quote=document.createElement("span");row.className="speaker-turn";select.dataset.continueTurn=String(index);select.add(new Option("Choose speaker…",""));select.add(new Option(d.characters.a.name,"a"));select.add(new Option(d.characters.b.name,"b"));select.value=turn.speaker||"";quote.textContent='“'+turn.line+'”';row.append(select,quote);box.append(row)});$("continue-silent-note").hidden=d.dialogue_turns.length>0;$("continue-video-compose").hidden=true;$("continue-video-review").hidden=false;$("continue-video-message").textContent=""}
  catch(err){$("continue-video-message").textContent=err.message}finally{submit.disabled=false}
};
$("continue-video-back").onclick=()=>{$("continue-video-review").hidden=true;$("continue-video-compose").hidden=false;$("continue-video-message").textContent=""};
$("continue-video-confirm").onclick=async()=>{if(!continueVideoDraft)return;let dialogue_turns=continueVideoDraft.dialogue_turns.map((turn,index)=>({speaker:$("continue-speaker-turns").querySelector(`[data-continue-turn="${index}"]`).value,line:turn.line}));if(dialogue_turns.some(turn=>!turn.speaker)){$("continue-video-message").textContent="Choose a speaker for every quoted line.";return}let button=$("continue-video-confirm");button.disabled=true;$("continue-video-message").textContent="Queuing continuation…";try{let d=await api("/api/v1/artifacts/"+continueArtifactId+"/continue",{method:"POST",body:JSON.stringify({content:continueVideoDraft.scene_text,dialogue_turns,confirmed:true})});continueVideoDialog.close();setBusy(true);await watch(d.job_id)}catch(err){$("continue-video-message").textContent=err.message}finally{button.disabled=false}};

const videoChainDialog=document.createElement("dialog");videoChainDialog.id="video-chain-dialog";
videoChainDialog.setAttribute("aria-label","Video sequence player");
videoChainDialog.innerHTML='<div class="dialog-head"><div><h2>Video sequence</h2><p class="note" id="video-chain-position"></p></div><button type="button" id="video-chain-close">Close</button></div><video id="video-chain-player" controls playsinline preload="metadata"></video><div class="dialog-actions video-chain-actions"><button type="button" id="video-chain-previous">Previous</button><button type="button" id="video-chain-fullscreen">Full screen</button><button type="button" id="video-chain-next">Next</button></div>';
document.body.append(videoChainDialog);let videoChain=[],videoChainIndex=0;
function showVideoChainItem(index,autoplay=false){
  if(!videoChain.length)return;videoChainIndex=Math.max(0,Math.min(index,videoChain.length-1));
  let player=$("video-chain-player");player.src=videoChain[videoChainIndex].url;
  $("video-chain-position").textContent="Clip "+(videoChainIndex+1)+" of "+videoChain.length;
  $("video-chain-previous").disabled=videoChainIndex===0;$("video-chain-next").disabled=videoChainIndex===videoChain.length-1;
  if(autoplay)player.play().catch(()=>{});
}
async function openVideoChain(artifactId){
  try{let data=await api("/api/v1/artifacts/"+artifactId+"/video-chain");videoChain=data.artifacts;showVideoChainItem(0);videoChainDialog.showModal()}
  catch(err){$("hint").textContent=err.message}
}
$("video-chain-player").addEventListener("ended",()=>{if(videoChainIndex+1<videoChain.length)showVideoChainItem(videoChainIndex+1,true)});
$("video-chain-previous").onclick=()=>showVideoChainItem(videoChainIndex-1,true);
$("video-chain-next").onclick=()=>showVideoChainItem(videoChainIndex+1,true);
$("video-chain-fullscreen").onclick=async()=>{let player=$("video-chain-player");try{
  if(player.requestFullscreen)await player.requestFullscreen();
  else if(player.webkitEnterFullscreen)player.webkitEnterFullscreen();
  else if(videoChainDialog.requestFullscreen)await videoChainDialog.requestFullscreen();
  else $("hint").textContent="Full-screen video is not supported by this browser.";
}catch(err){$("hint").textContent="The browser could not enter full screen."}};
$("video-chain-close").onclick=()=>{let player=$("video-chain-player");player.pause();player.removeAttribute("src");player.load();videoChainDialog.close()};
